{
  "path": [
    {
      "step": 1,
      "course_id": "EDX1719",
      "rationale": "This foundational statistics course covers introductory statistics, probability, and estimation, providing a solid base for further learning."
    },
    {
      "step": 2,
      "course_id": "COU4493",
      "rationale": "This course builds on the foundational concepts of statistics, introducing students to data analysis, probability, and statistics, as well as AI and data science."
    },
    {
      "step": 3,
      "course_id": "EDX2160",
      "rationale": "This course focuses on learning to love statistics, covering statistical tests, data representation, and statistical significance, providing a deeper understanding of statistical concepts."
    },
    {
      "step": 4,
      "course_id": "COU2716",
      "rationale": "This course delves into data literacy, covering statistical hypothesis testing, measurement uncertainty, and visualization, helping students to critically evaluate data and make informed decisions."
    },
    {
      "step": 5,
      "course_id": "EDX2607",
      "rationale": "This advanced course covers key concepts in statistics and hypothesis testing, including confidence intervals, hypothesis tests, and statistical analysis, providing a comprehensive understanding of statistical concepts."
    }
  ]
}

{
  "path": [
    {
      "step": 1,
      "course_id": "EDX1789",
      "rationale": "Foundational course in computer science and programming using Python, covering basic concepts such as computation, algorithms, and data structures."
    },
    {
      "step": 2,
      "course_id": "EDX1479",
      "rationale": "Builds on the foundational concepts from EDX1789, focusing on how to represent information as data, use examples and tests to clarify program behavior, and simplify program structure using common patterns."
    },
    {
      "step": 3,
      "course_id": "EDX2761",
      "rationale": "Introduces object-oriented programming and common search and sorting algorithms, building on the data structures and algorithms learned in EDX1479."
    },
    {
      "step": 4,
      "course_id": "EDX2330",
      "rationale": "Covers advanced data structures and algorithms, including dynamic arrays, linked structures, and graph algorithms, building on the object-oriented programming and algorithmic thinking learned in EDX2761."
    },
    {
      "step": 5,
      "course_id": "EDX1055",
      "rationale": "Introduces object-oriented programming concepts, including objects, classes, inheritance, and interfaces, building on the data structures and algorithms learned in EDX2330."
    },
    {
      "step": 6,
      "course_id": "EDX1350",
      "rationale": "Focuses on object-oriented implementation using C++, building on the object-oriented programming concepts learned in EDX1055."
    }
  ]
}

