{
  "path": [
    {
      "step": 1,
      "course_id": "EDX1848",
      "rationale": "This foundational course provides strategies for approaching math effectively, correcting misconceptions, and building confidence in math abilities."
    },
    {
      "step": 2,
      "course_id": "EDX1017",
      "rationale": "This course builds on the foundational skills from EDX1848, providing a grounding in arithmetic and algebra, an overview of functions, and an introduction to financial mathematics."
    },
    {
      "step": 3,
      "course_id": "EDX2137",
      "rationale": "This course further develops algebraic skills, introducing functions, function characteristics, and properties, as well as statistical regression and matrix methods."
    },
    {
      "step": 4,
      "course_id": "EDX1281",
      "rationale": "This advanced course applies mathematical concepts to real-world problems, including linear equations, quadratic and exponential relationships, and calculus for optimization."
    }
  ]
}

