    {
      "step": 1,
      "course_id": "COU4621",
      "rationale": "Begin with foundational knowledge of Mandarin Chinese, covering the basics of the language, including pronunciation, grammar, and vocabulary."
    },
    {
      "step": 2,
      "course_id": "COU1740",
      "rationale": "Build on the foundational knowledge by expanding vocabulary and improving listening and speaking skills, with a focus on practical, real-world applications for business travel."
    },
    {
      "step": 3,
      "course_id": "COU4946",
      "rationale": "Further develop practical skills in Mandarin Chinese, including daily expressions, vocabulary, and grammar, with an emphasis on functional communication for business travel."
    },
    {
      "step": 4,
      "course_id": "COU6331",
      "rationale": "Improve listening and speaking skills in Mandarin Chinese, with a focus on real-life situations and practical applications for business travel."
    },
    {
      "step": 5,
      "course_id": "COU3679",
      "rationale": "Develop advanced skills in Mandarin Chinese, including proficiency in vocabulary, grammar, and communication, with a focus on real-world applications for business travel."
    }
  ]
}

{
  "path": [
    {
      "step": 1,
      "course_id": "EDX1485",
      "rationale": "Foundational conversational English skills are essential for effective communication in a technical workplace."
    },
    {
      "step": 2,
      "course_id": "EDX2106",
      "rationale": "Building on conversational skills, this course helps learners plan, research, and structure a piece of writing according to the needs of a specific reader and purpose."
    },
    {
      "step": 3,
      "course_id": "EDX792",
      "rationale": "With writing skills developed, learners can refine their persuasive writing techniques and essay development in this course."
    },
    {
      "step": 4,
      "course_id": "EDX260",
      "rationale": "Advanced writing skills are complemented by this course, which focuses on using English verbal tenses in context and listening and speaking in English."
    },
    {
      "step": 5,
      "course_id": "EDX3082",
      "rationale": "Effective communication in a technical workplace requires strong speaking skills, which this course helps learners develop through pronunciation, rhythm, and persuasive presentation techniques."
    }
  ]
}

