{
  "path": [
    {
      "step": 1,
      "course_id": "EDX2212",
      "rationale": "Foundational course in finance, covering essential concepts such as time value of money, capital budgeting, and financial reporting."
    },
    {
      "step": 2,
      "course_id": "EDX3047",
      "rationale": "Builds on the foundational concepts, introducing essential career skills for investment banking and finance, including industry jargon and financial analysis."
    },
    {
      "step": 3,
      "course_id": "EDX3298",
      "rationale": "Develops managerial finance skills, enabling learners to contribute to financial discussions and decision-making, and understand financial reports and forecasting."
    },
    {
      "step": 4,
      "course_id": "EDX490",
      "rationale": "Introduces credit risk management in banking, covering the role of credit risk in lending decisions, Basel norms, and credit portfolio management."
    },
    {
      "step": 5,
      "course_id": "EDX2547",
      "rationale": "Explores bond, equity markets, and financial regulation, including the role of debt and equity in a firm's capital structure and the calculation of credit spreads and yields."
    },
    {
      "step": 6,
      "course_id": "EDX1121",
      "rationale": "Develops corporate finance and valuation methods, including capital budgeting, cost of capital, and the capital asset pricing model (CAPM)."
    },
    {
      "step": 7,
      "course_id": "EDX3314",
      "rationale": "Applies corporate finance and valuation methods to real-world scenarios, including mergers and acquisitions, capital structure, and payout policy."
    },
    {
      "step": 8,
      "course_id": "EDX490",
      "rationale": "Introduces advanced credit risk management, including stress testing, reverse stress testing, and comprehensive capital analysis and review (CCAR)."
    },
    {
      "step": 9,
      "course_id": "EDX2924",
      "rationale": "Develops financial analysis skills for insurance companies, including financial statement analysis, impairment tests, and capital and surplus analysis."
    },
    {
      "step": 10,
      "course_id": "EDX3268",
      "rationale": "Explores fintech, including the impact of blockchain, AI, and big data on financial services, and the role of data and security in data-driven finance."
    },
    {
      "step": 11,
      "course_id": "EDX3307",
      "rationale": "Introduces sustainable finance, including the environmental and social sustainability challenges facing financial systems and business, and the skills to steer capital for a sustainable future."
    },
    {
      "step": 12,
      "course_id": "EDX448",
      "rationale": "Develops financial accounting skills, including financial reporting, accounting systems, and financial statement analysis."
    },
    {
      "step": 13,
      "course_id": "EDX272",
      "rationale": "Introduces risk management, including risk analysis, risk measurement, and risk management tools, and the role of risk management in financial decision-making."
    },
    {
      "step": 14,
      "course_id": "EDX2547",
      "rationale": "Explores advanced risk management, including stress testing, reverse stress testing, and comprehensive capital analysis and review (CCAR)."
    },
    {
      "step": 15,
      "course_id": "EDX490",
      "rationale": "Develops financial analysis skills for insurance companies, including financial statement analysis, impairment tests, and capital and surplus analysis."
    }
  ]
}

